/**
 * Voice Intelligence — server functions (D327).
 *
 * STUB STATUS: signatures + zod schemas are final (cross-stream contract).
 * Stream B implements the handlers; every handler currently throws.
 * Stream C: import these functions for client calls and mock them in
 * tests — DO NOT edit this file (Stream B owns it).
 */
import { createServerFn } from "@tanstack/react-start";
import { z } from "zod";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";
import { VOICE_CATEGORY_IDS } from "./types";
import type {
  CompareVoicesResult,
  PreviewVoiceResult,
  SynthesizeNarrationResult,
  TtsProviderStatus,
  VoiceAvailabilityInfo,
  VoiceCharactersPayload,
  VoiceProfile,
} from "./contracts";
import type { VoiceCostEstimate, VoiceSettings } from "./types";

const notImplemented = (): never => {
  throw new Error("Voice Intelligence backend not implemented yet (Stream B).");
};

/* ── schemas ───────────────────────────────────────────────────────────── */

export const VoiceSettingsSchema = z.object({
  stability: z.number().min(0).max(1),
  similarityBoost: z.number().min(0).max(1),
  style: z.number().min(0).max(1),
  speed: z.number().min(0.7).max(1.2),
  speakerBoost: z.boolean(),
});

export const VoiceSelectionSchema = z.object({
  languageCode: z.string().min(2).max(8),
  categoryId: z.enum(VOICE_CATEGORY_IDS).nullable(),
  characterId: z.string().min(1).max(80),
  modelId: z.string().min(1).max(80),
  settings: VoiceSettingsSchema,
  customised: z.boolean(),
});

export const PreviewVoiceSchema = z.object({
  characterId: z.string().min(1).max(80),
  text: z.string().min(1).max(500).optional(),
  modelId: z.string().min(1).max(80).optional(),
});

export const CompareVoicesSchema = z.object({
  characterIds: z.array(z.string().min(1).max(80)).min(1).max(3),
  text: z.string().min(1).max(500),
  modelId: z.string().min(1).max(80).optional(),
});

export const SynthesizeNarrationSchema = z.object({
  text: z.string().min(1).max(8000),
  selection: VoiceSelectionSchema,
  projectId: z.string().uuid().optional(),
});

export const CharacterIdSchema = z.object({
  characterId: z.string().min(1).max(80),
});

export const ChannelDefaultGetSchema = z.object({
  scope: z.string().min(1).max(160),
});

export const ChannelDefaultSaveSchema = z.object({
  scope: z.string().min(1).max(160),
  selection: VoiceSelectionSchema,
});

export const VoiceProfileSaveSchema = z.object({
  name: z.string().min(1).max(80),
  selection: VoiceSelectionSchema,
});

export const VoiceProfileDeleteSchema = z.object({
  id: z.string().uuid(),
});

export const TrackVoiceEventSchema = z.object({
  event: z.string().min(1).max(80),
  metadata: z.record(z.string(), z.unknown()).optional(),
});

export const EstimateVoiceCostSchema = z.object({
  text: z.string().min(1).max(20000),
  modelId: z.string().min(1).max(80).optional(),
  languageCode: z.string().min(2).max(8).optional(),
});

export const ProjectVoiceConfigGetSchema = z.object({
  projectId: z.string().uuid(),
});

export const ProjectVoiceConfigSaveSchema = z.object({
  projectId: z.string().uuid(),
  selection: VoiceSelectionSchema,
});

/* ── catalog / models / status ─────────────────────────────────────────── */

export const listVoiceCharacters = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async (): Promise<VoiceCharactersPayload> => notImplemented());

export const listVoiceModels = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async () => notImplemented());

export const getVoiceProviderStatus = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async (): Promise<TtsProviderStatus> => notImplemented());

export const checkVoiceAvailability = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .inputValidator(CharacterIdSchema)
  .handler(async (): Promise<VoiceAvailabilityInfo> => notImplemented());

/* ── preview / compare / synthesize ────────────────────────────────────── */

export const previewVoice = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(PreviewVoiceSchema)
  .handler(async (): Promise<PreviewVoiceResult> => notImplemented());

export const compareVoices = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(CompareVoicesSchema)
  .handler(async (): Promise<CompareVoicesResult> => notImplemented());

export const synthesizeNarration = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(SynthesizeNarrationSchema)
  .handler(async (): Promise<SynthesizeNarrationResult> => notImplemented());

export const estimateVoiceCost = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .inputValidator(EstimateVoiceCostSchema)
  .handler(async (): Promise<VoiceCostEstimate> => notImplemented());

/* ── favorites / channel defaults / profiles ───────────────────────────── */

export const getVoiceFavorites = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async (): Promise<{ characterIds: string[] }> => notImplemented());

export const toggleVoiceFavorite = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(CharacterIdSchema)
  .handler(async (): Promise<{ favorited: boolean }> => notImplemented());

export const getChannelVoiceDefault = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .inputValidator(ChannelDefaultGetSchema)
  .handler(async (): Promise<{ selection: import("./types").VoiceSelection | null }> =>
    notImplemented(),
  );

export const saveChannelVoiceDefault = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(ChannelDefaultSaveSchema)
  .handler(async (): Promise<{ ok: true }> => notImplemented());

export const listVoiceProfiles = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async (): Promise<{ profiles: VoiceProfile[] }> => notImplemented());

export const saveVoiceProfile = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(VoiceProfileSaveSchema)
  .handler(async (): Promise<{ profile: VoiceProfile }> => notImplemented());

export const deleteVoiceProfile = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(VoiceProfileDeleteSchema)
  .handler(async (): Promise<{ ok: true }> => notImplemented());

/* ── project persistence / analytics ───────────────────────────────────── */

export const getProjectVoiceConfig = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .inputValidator(ProjectVoiceConfigGetSchema)
  .handler(async (): Promise<{ selection: import("./types").VoiceSelection | null }> =>
    notImplemented(),
  );

export const saveProjectVoiceConfig = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(ProjectVoiceConfigSaveSchema)
  .handler(async (): Promise<{ ok: true }> => notImplemented());

export const trackVoiceEvent = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(TrackVoiceEventSchema)
  .handler(async (): Promise<{ ok: true }> => notImplemented());

export type { VoiceSettings };
